import 'package:flutter/material.dart';
import 'package:sensors_plus/sensors_plus.dart';
import 'dart:async';

class MotionSensorPage extends StatefulWidget {
  @override
  _MotionSensorPageState createState() => _MotionSensorPageState();
}

class _MotionSensorPageState extends State<MotionSensorPage> {
  late StreamSubscription<AccelerometerEvent> _accelerometerSubscription;
  double _x = 0, _y = 0, _z = 0;

  @override
  void initState() {
    super.initState();
    // Listen to accelerometer events
    _accelerometerSubscription = accelerometerEventStream().listen((event) {
      setState(() {
        _x = event.x;
        _y = event.y;
        _z = event.z;
      });
    });
  }

  @override
  void dispose() {
    // Don't forget to cancel the subscription
    _accelerometerSubscription.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("Accelerometer Demo")),
      body: Center(
        child: Text(
          'X: ${_x.toStringAsFixed(2)}\nY: ${_y.toStringAsFixed(2)}\nZ: ${_z.toStringAsFixed(2)}',
          style: TextStyle(fontSize: 24),
          textAlign: TextAlign.center,
        ),
      ),
    );
  }
}

